 ('salarie', 'Salarié', 'demo_salarie', 'sal_id', 'sal_proprietes', '{"libelle":"Salarié","titre":"[prenom] [nom]","sous_titre":"[matricule] · [poste]","sections":[{"code":"entreprise","titre":"Entreprise","groupes":[{"titre":"Identité","champs":["matricule","nom","prenom"]},{"titre":"Emploi","champs":["agence","service","poste","type_mo","statut","date_entree","actif"]},{"titre":"Coordonnées professionnelles","champs":["email","telephone"]},{"titre":"Rémunération","champs":["salaire_brut","heures_mois"]},{"titre":"Note professionnelle","champs":["commentaire"],"largeur":"plein"}]},{"code":"prive","titre":"Privé (RGPD)","groupes":[{"titre":"État civil","champs":["date_naissance","num_secu"]},{"titre":"Coordonnées personnelles","champs":["adresse","code_postal","ville","telephone_perso","email_perso"]},{"titre":"Personne à prévenir","champs":["contact_nom","contact_telephone"]},{"titre":"Note personnelle","champs":["note_perso"],"largeur":"plein"}]}],"champs":[{"code":"matricule","libelle":"Matricule","colonne":"sal_matricule","type":"texte","obligatoire":true,"longueur":10,"saisie":"creation","non_copie":true,"aide":"Identifiant unique, saisi à la création"},{"code":"nom","libelle":"Nom","colonne":"sal_nom","type":"texte","obligatoire":true,"longueur":60},{"code":"prenom","libelle":"Prénom","colonne":"sal_prenom","type":"texte","obligatoire":true,"longueur":60},{"code":"date_naissance","libelle":"Date de naissance","colonne":"sal_date_naissance","type":"date","confidentiel":true},{"code":"num_secu","libelle":"N° de sécurité sociale","colonne":"sal_num_secu","type":"texte","confidentiel":true,"non_copie":true,"longueur":21,"format":"regex:^[12] ?[0-9]{2} ?[0-9]{2} ?[0-9]{2} ?[0-9]{3} ?[0-9]{3} ?[0-9]{2}$","aide":"13 chiffres + clé (espaces acceptés)"},{"code":"service","libelle":"Service","colonne":"sal_service","type":"liste","obligatoire":true,"options":[{"valeur":"Chantier","libelle":"Chantier"},{"valeur":"Bureau","libelle":"Bureau"},{"valeur":"Atelier","libelle":